inline ulong rotl(const ulong x,const int k){return (x<<k)|(x>>(64-k));}
inline ulong splitmix(thread ulong& x){x+=0x9e3779b97f4a7c15ul;ulong z=x;z=(z^(z>>30))*0xbf58476d1ce4e5b9ul;z=(z^(z>>27))*0x94d049bb133111ebul;return z^(z>>31);}
