func rotl(_ x:UInt64,_ k:UInt64)->UInt64 {(x << k) | (x >> (64-k))}
func splitmix(_ x:inout UInt64)->UInt64{x &+= 0x9e3779b97f4a7c15;var z=x;z=(z^(z>>30)) &* 0xbf58476d1ce4e5b9;z=(z^(z>>27)) &* 0x94d049bb133111eb;return z^(z>>31)}
